-- Deletion retains only inert goal/Proposal fences. They prevent a deleted
-- objective becoming a fresh budget or an unassociated late manual confirmation.
create function turn_private.erase_trip_objective_v1(task uuid) returns void
language plpgsql security definer set search_path='' as $$
declare s turn_private.service_tasks%rowtype;b jsonb;
begin
 select * into s from turn_private.service_tasks where id=task;
 if s.trip_objective is null or s.trip_objective->>'outcome'='erased' then return;end if;
 if not pg_try_advisory_xact_lock(hashtextextended(s.owner_id::text,34)) then raise exception 'TURN_SOURCE_BUSY';end if;
 -- Release while the original thread/Trip scope still exists; never reverse a settlement.
 update turn_private.service_task_capacity set state='released',released_at=clock_timestamp() where task_id=s.id and state='reserved';
 b:=jsonb_build_object('schemaVersion','trip-service-task-erased/1','outcome','erased','goalId',s.trip_objective->'goalId');
 if s.trip_objective->>'proposalId' is not null then b:=b||jsonb_build_object('proposalId',s.trip_objective->'proposalId');end if;
 update turn_private.service_tasks set trip_objective=b where id=s.id;
end $$;
revoke all on function turn_private.erase_trip_objective_v1(uuid) from public,anon,authenticated,service_role;

-- Only original deletion facts permit this irreversible reduction. A client,
-- model, task update or forged session setting cannot authorize erasure.
create or replace function turn_private.guard_metered_task_type()
returns trigger language plpgsql security definer set search_path='' as $$
begin
 if (old.trip_objective is not null or exists(select 1 from turn_private.service_task_capacity where task_id=new.id))
 and (new.expected_result is distinct from old.expected_result or new.owner_id is distinct from old.owner_id or new.thread_id is distinct from old.thread_id) then raise exception 'SERVICE_TASK_CAPACITY_SCOPE_CONFLICT';end if;
 if old.trip_objective is null and new.trip_objective is not null then raise exception 'SERVICE_TASK_CAPACITY_SCOPE_CONFLICT';end if;
 if old.trip_objective is not null and new.trip_objective is distinct from old.trip_objective then
 if new.trip_objective->>'outcome'='erased' then
 if new.trip_objective is distinct from (jsonb_build_object('schemaVersion','trip-service-task-erased/1','outcome','erased','goalId',old.trip_objective->'goalId')
 ||case when old.trip_objective->>'proposalId' is null then '{}'::jsonb else jsonb_build_object('proposalId',old.trip_objective->'proposalId') end)
 or not (exists(select 1 from turn_private.text_content where turn_id=old.goal_turn_id and hidden_at is not null)
 or not exists(select 1 from turn_private.assistant_messages where id=(old.trip_objective->>'messageId')::uuid and owner_id=old.owner_id)
 or exists(select 1 from privacy_private.trip_deletions where trip_id=(old.trip_objective->>'tripId')::uuid and owner_id=old.owner_id)
 or not exists(select 1 from auth.users where id=old.owner_id)) then raise exception 'SERVICE_TASK_ERASURE_AUTHORITY_REQUIRED';end if;
 elsif old.trip_objective->>'outcome'='erased' or (new.trip_objective-array['proposalId','proposalRevision','proposalDigest','producerBinding','outcome','settledVersion']) is distinct from (old.trip_objective-array['proposalId','proposalRevision','proposalDigest','producerBinding','outcome','settledVersion']) then raise exception 'SERVICE_TASK_CAPACITY_SCOPE_CONFLICT';end if;
 end if;return new;
end $$;

create function turn_private.trip_objective_source_erased_v1() returns trigger
language plpgsql security definer set search_path='' as $$
declare s record;
begin
 if tg_table_name='text_content' then
 if new.hidden_at is not null then for s in select id from turn_private.service_tasks where owner_id=new.owner_id and goal_turn_id=new.turn_id and trip_objective is not null loop perform turn_private.erase_trip_objective_v1(s.id);end loop;end if;
 elsif tg_table_name='assistant_messages' then
 for s in select id from turn_private.service_tasks where owner_id=old.owner_id and trip_objective->>'messageId'=old.id::text loop perform turn_private.erase_trip_objective_v1(s.id);end loop;
 elsif tg_table_name='trip_deletions' then
 for s in select id from turn_private.service_tasks where owner_id=new.owner_id and trip_objective->>'tripId'=new.trip_id::text loop perform turn_private.erase_trip_objective_v1(s.id);end loop;
 elsif tg_table_name='users' then
 -- AFTER the real account row disappears; no unrelated role can invoke this.
 for s in select id from turn_private.service_tasks where owner_id=old.id and trip_objective is not null loop perform turn_private.erase_trip_objective_v1(s.id);end loop;
 end if;return null;
end $$;
